"""Unit tests for the cached-G-code parser and X/Y translation."""

from __future__ import annotations

import pytest

from backend.batching.gcode import (
    GcodeFormatError,
    parse_duration,
    parse_gcode,
    translate_xy,
)

SAMPLE = """\
; HEADER_BLOCK_START
; generated by OrcaSlicer 2.5.0
; HEADER_BLOCK_END

; EXECUTABLE_BLOCK_START
G90
G21
M83
G28
G92 E0
M104 S200
;LAYER_CHANGE
;Z:0.2
;HEIGHT:0.2
G92 E0

;LAYER_CHANGE
;Z:0.2
G92 E0
G1 E-.8 F1800
G1 X10 Y10 F7200
G1 Z.6
G1 Z.2
G1 E.8 F1800
;TYPE:Skirt
G1 X8 Y8 E.1
G1 X28 Y8 E.5
G1 X28 Y28 E.5
G1 X8 Y28 E.5
;TYPE:Wall
G1 X10 Y10 E.2
G1 X26 Y10 E.4
G1 X26 Y26 E.4
;LAYER_CHANGE
;Z:0.4
G92 E0
G1 X11 Y11 E.2
G1 X25 Y25 E.4
; stop printing object
G1 E-.8 F1800
M106 S0
M104 S0
G28 X0
M84
; EXECUTABLE_BLOCK_END

; filament used [mm] = 1234.50
; estimated printing time (normal mode) = 1h 2m 3s
"""


def test_parse_layers_and_z() -> None:
    parsed = parse_gcode(SAMPLE, source="sample")
    # the duplicate ;LAYER_CHANGE at Z:0.2 collapses into one layer
    assert parsed.layer_heights == [0.2, 0.4]
    assert len(parsed.layers) == 2


def test_parse_start_and_end_blocks() -> None:
    parsed = parse_gcode(SAMPLE, source="sample")
    assert "M83" in parsed.start_lines
    assert "M104 S200" in parsed.start_lines
    assert not any(ln.startswith(";LAYER_CHANGE") for ln in parsed.start_lines)
    assert "M104 S0" in parsed.end_lines
    assert "M84" in parsed.end_lines
    assert not any("E" in ln and ln.startswith("G1") for ln in parsed.end_lines)


def test_footprint_includes_skirt() -> None:
    parsed = parse_gcode(SAMPLE, source="sample")
    assert parsed.footprint == pytest.approx((8.0, 8.0, 28.0, 28.0))
    assert parsed.footprint_size(margin=1.0) == pytest.approx((22.0, 22.0))


def test_duration_and_filament() -> None:
    parsed = parse_gcode(SAMPLE, source="sample")
    assert parsed.duration_s == pytest.approx(3723.0)
    assert parsed.filament_mm == pytest.approx(1234.50)


def test_parse_duration_formats() -> None:
    assert parse_duration("29m 12s") == pytest.approx(1752.0)
    assert parse_duration("45s") == pytest.approx(45.0)
    assert parse_duration("2h 0m 5s") == pytest.approx(7205.0)
    assert parse_duration("nothing here") is None


def test_missing_layer_marker_rejected() -> None:
    with pytest.raises(GcodeFormatError):
        parse_gcode("G90\nG28\nM84\n", source="bad")


def test_translate_xy_shifts_only_motion() -> None:
    assert translate_xy("G1 X10.5 Y-3 E.2 F1500", 5.0, 2.0) == "G1 X15.5 Y-1 E.2 F1500"
    assert translate_xy("G0 X1 Y2", 0.25, 0.5) == "G0 X1.25 Y2.5"
    assert translate_xy("M205 X10.00 Y10.00 Z0.20 E2.50", 5.0, 5.0) == "M205 X10.00 Y10.00 Z0.20 E2.50"
    assert translate_xy("G1 Z.6", 5.0, 5.0) == "G1 Z.6"
    assert translate_xy(";TYPE:Skirt", 5.0, 5.0) == ";TYPE:Skirt"


def test_translate_xy_rejects_arcs() -> None:
    with pytest.raises(GcodeFormatError):
        translate_xy("G2 X10 Y10 I1 J0 E.1", 1.0, 1.0)


def test_time_elapsed_fallback() -> None:
    text = ";LAYER_CHANGE\n;Z:0.2\nG1 X1 Y1 E.1\n;TIME_ELAPSED:42.5\n"
    parsed = parse_gcode(text, source="t")
    assert parsed.duration_s == pytest.approx(42.5)
